<template><section class="portal-safety"><header v-if="!compact" class="auricwell-documents"><img src="/auricwell/mark.svg" alt="" /><div><strong>AuricWell</strong><h3>Documents &amp; forms</h3></div></header><h3 v-if="compact">Shared forms &amp; documents</h3><p v-if="error" role="alert">{{ error }}</p><p v-if="loading">Loading shared plans…</p><p v-else-if="!shares.length&&!error">No forms are waiting for you here.</p><nav aria-label="Shared clinical documents"><button v-for="s in shares" :key="s.id" type="button" @click="open(s.id)">{{ s.title||'Clinical document' }} · version {{ s.version }} · {{ s.signedAt?'Completed':s.copyOnly?'Shared copy':'Review & sign →' }}</button></nav><template v-if="plan"><p v-if="plan.version!==plan.currentVersion" class="notice">This is an earlier version. Your care team will share the revised plan when it is ready. This copy remains available for reference.</p><p v-if="plan.revocation" class="notice">This release authorization was revoked on {{ new Date(plan.revocation.recordedAt).toLocaleDateString() }}. The signed copy is retained for your records.</p><p v-if="plan.reviewStatus" class="notice">Form review: {{ plan.reviewStatus==='reviewed'?'Reviewed':'Awaiting staff review' }}.</p><button v-if="plan.template.key==='release-of-information'&&!plan.revocation" type="button" @click="revokeAuthorization">Revoke authorization</button>
    <p v-if="editingUpdate" class="notice">Complete the fields below, then sign to submit your form for staff review.</p><ClinicalDocumentCopy v-if="!editingUpdate" :document-element="()=>readDocument?.$el" :attendance="plan.template.key==='attendance-verification'" /><SafetyPlanDocument ref="readDocument" :model-value="editingUpdate?updateData:plan.data" :editable="editingUpdate" @update:model-value="updateData=$event" :template="plan.template" :branding="plan.branding" :version="plan.version" :signers="plan.signers" /><SafetyPlanSigning v-if="mySigner&&!mySigner.copyOnly&&!mySigner.signedAt&&!plan.revocation&&plan.version===plan.currentVersion" :key="`${shareId}:${plan.version}`" :plan="plan" :signer="mySigner" :share-id="shareId" :update-data="editingUpdate?updateData:undefined" portal @signed="signed" @cancel="plan=null" /><p v-else-if="mySigner?.signedAt" role="status">Your signature has been saved with this version.</p></template></section></template>
<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import liveApi from '../../services/api';
import {inject} from 'vue';
const api=inject('clinicalFormsHttp',liveApi);
import SafetyPlanDocument from './SafetyPlanDocument.vue';
import ClinicalDocumentCopy from './ClinicalDocumentCopy.vue';
import SafetyPlanSigning from './SafetyPlanSigning.vue';
const props=defineProps({clientId:[Number,String],compact:Boolean});
const readDocument=ref(null);
const shares=ref([]),plan=ref(null),shareId=ref(null),loading=ref(false),error=ref('');let generation=0,timer;
const updateData=ref({});
const editingUpdate=computed(()=>(mySigner.value?.allowCompletion||plan.value?.template.key==='client-information-update')&&!mySigner.value?.copyOnly&&!plan.value?.revocation&&!mySigner.value?.signedAt&&plan.value?.version===plan.value?.currentVersion);
const mySigner=computed(()=>plan.value?.signers.find(s=>s.id===plan.value.mySignerId));
const message=e=>e.response?.data?.error?.message||'Shared safety plans are temporarily unavailable.';
async function load(){const g=++generation;shares.value=[];plan.value=null;shareId.value=null;error.value='';if(!props.clientId)return;loading.value=true;try{const {data}=await api.get('/clinical-forms/portal',{params:{clientId:props.clientId}});if(g===generation)shares.value=data.shares;}catch(e){if(g===generation)error.value=message(e);}finally{if(g===generation)loading.value=false;}}
async function open(id){const g=++generation;plan.value=null;shareId.value=id;error.value='';try{const {data}=await api.get(`/clinical-forms/portal/${id}`);if(g===generation){plan.value=data;updateData.value=JSON.parse(JSON.stringify(data.data));}}catch(e){if(g===generation)error.value=message(e);}}
async function refresh(){if(!plan.value||document.hidden)return;const g=generation,id=shareId.value;try{const {data}=await api.get(`/clinical-forms/portal/${id}`,{skipGlobalLoading:true});if(g===generation)plan.value=data;}catch(e){if(g===generation){plan.value=null;error.value=message(e);}}}
async function signed(){if(editingUpdate.value){await load();if(shares.value.length)await open(shares.value[0].id);}else await open(shareId.value);}
async function revokeAuthorization(){const reason=window.prompt('Write your request to revoke this release authorization. Past disclosures cannot be undone.');if(!reason)return;try{const {data}=await api.post(`/clinical-forms/portal/${shareId.value}/revoke-authorization`,{version:plan.value.currentVersion,reason,confirm:true});plan.value=data;}catch(e){error.value=message(e);}}
watch(()=>props.clientId,load,{immediate:true});onMounted(()=>{timer=setInterval(refresh,15000);});onBeforeUnmount(()=>{++generation;clearInterval(timer);plan.value=null;shares.value=[];});
</script>
<style scoped>.auricwell-documents{display:flex;align-items:center;gap:12px}.auricwell-documents img{width:36px;height:36px}.auricwell-documents h3{margin:4px 0}.auricwell-documents strong{color:#175b48}.portal-safety{margin:24px 0;padding:22px;border:1px solid #d5e1d7;border-radius:12px;background:#fbfdfb}.portal-safety>p{line-height:1.7}nav{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}button{font:inherit;padding:12px 16px;background:white;color:#175b48;border:1px solid #9fb9aa;border-radius:8px;cursor:pointer}.notice{padding:16px;background:#f8f1db}[role=alert]{color:#91281f}[role=status]{color:#175b48}</style>
